prompt --application/shared_components/user_interface/templates/region/brutal_block
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(778975356949916180)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TBrutalBlock #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <header class="amc-TBrutalBlock-header">',
'    <div class="amc-TBrutalBlock-label">',
'      <span class="amc-TBrutalBlock-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TBrutalBlock-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'    </div>',
'    <div class="amc-TBrutalBlock-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'  </header>',
'  <div class="amc-TBrutalBlock-body">#BODY##SUB_REGIONS#</div>',
'  <footer class="amc-TBrutalBlock-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'</section>'))
,p_page_plug_template_name=>'AMC Brutal Block'
,p_internal_name=>'AMC_TPL_BRUTAL_BLOCK'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-brutal-block.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template in neo-brutalist style. The ink border and hard shadow use the theme text color, so they invert in dark styles; the shadow falls to the end side and flips in right-to-left pages. The title and icon sit in a tilted label that breaks out of the top edge; Help, Edit, Change, Copy, Delete and Create buttons sit in the header band, Previous, Close and Next in the footer. Template options color the band warning, success, danger or ink, move the shadow to the start side, or remove the body padding. The label straightens and the shadow grows while the region has hover or keyboard focus; under reduced motion the change is instant. In forced-colors mode the shadow is removed and the borders use system colors.'
);
end;
